'use strict';
const DATA=window.APP_DATA||{fish:[],questions:[],rules:{states:[],rules:{},sources:{}}};
const VERSION='1.1.0';
const NAV=[['home','Übersicht','⌂'],['trophies','Meine Trophäen','♛'],['fish','Fischkunde','♓'],['exam','Angelschein','▤'],['rules','Schonzeiten & Maße','⚖'],['clock','Angelzeit-Uhr','◷'],['stats','Statistik','▥'],['gear','Ausrüstung & Köder','⚓'],['spots','Spots & Routen','⌖'],['backup','Backup & Einstellungen','⚙']];
const blank=()=>({version:VERSION,createdAt:new Date().toISOString(),state:'Nordrhein-Westfalen',trophies:[],sessions:[],examHistory:[],spots:[],timer:{running:false,paused:false,startedAt:null,pausedAt:null,pausedMs:0},prefs:{}});
let S=blank(),page='home',quiz=null,fishFilter={search:'',water:'Alle',group:'Alle'},trophyFilter='Alle',searchTimer=null,lastSave=Promise.resolve(),selectedPhotos=[],editId=null,toastTimeout,gearTab='Alle';
const $=(q,root=document)=>root.querySelector(q),$$=(q,root=document)=>[...root.querySelectorAll(q)];
const h=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=(n,max=1)=>new Intl.NumberFormat('de-DE',{maximumFractionDigits:max}).format(Number(n)||0);
const dateDe=d=>{if(!d)return '–';let dt=new Date(d);return isNaN(dt)?'–':dt.toLocaleDateString('de-DE')};
const datetimeDe=d=>{if(!d)return '–';let dt=new Date(d);return isNaN(dt)?'–':dt.toLocaleString('de-DE',{dateStyle:'short',timeStyle:'short'})};
const isoLocal=d=>{const v=d||new Date();return new Date(v.getTime()-v.getTimezoneOffset()*60000).toISOString().slice(0,16)};
const id=()=>(globalThis.crypto?.randomUUID?.()||Date.now()+'-'+Math.random().toString(36).slice(2));
const weightText=g=>g>0?(g>=1000?`${fmt(g/1000,3)} kg`:`${fmt(g,0)} g`):'Nicht gewogen';
const timeText=sec=>{sec=Math.max(0,Math.floor(sec||0));return `${String(Math.floor(sec/3600)).padStart(2,'0')}:${String(Math.floor(sec/60)%60).padStart(2,'0')}:${String(sec%60).padStart(2,'0')}`};
const durationText=sec=>{let v=Number(sec)||0;return `${fmt(Math.floor(v/3600),0)} h ${String(Math.floor(v/60)%60).padStart(2,'0')} min`};
const arr=x=>Array.isArray(x)?x:[];
let dbPromise;
function openDB(){if(!('indexedDB' in globalThis))return Promise.reject(new Error('IndexedDB nicht verfügbar'));if(!dbPromise)dbPromise=new Promise((res,rej)=>{let req=indexedDB.open('PetriHeilPro',1);req.onupgradeneeded=()=>{if(!req.result.objectStoreNames.contains('app'))req.result.createObjectStore('app')};req.onsuccess=()=>res(req.result);req.onerror=()=>rej(req.error)});return dbPromise}
async function load(){try{let db=await openDB();const data=await new Promise((res,rej)=>{let t=db.transaction('app','readonly').objectStore('app').get('state');t.onsuccess=()=>res(t.result);t.onerror=()=>rej(t.error)});if(data&&typeof data==='object')S={...blank(),...data}}catch(e){try{let x=localStorage.getItem('petri-heil-pro');if(x)S={...blank(),...JSON.parse(x)};toast('Speicherung eingeschränkt: bitte Backups sichern.')}catch{}}normalize()}
function normalize(){S.trophies=arr(S.trophies);S.sessions=arr(S.sessions);S.examHistory=arr(S.examHistory);S.spots=arr(S.spots);S.timer={...blank().timer,...S.timer};if(!DATA.rules.states.includes(S.state))S.state='Nordrhein-Westfalen';S.prefs=S.prefs||{}}
async function dbSave(){try{const db=await openDB();await new Promise((res,rej)=>{let req=db.transaction('app','readwrite').objectStore('app').put(S,'state');req.onsuccess=()=>res();req.onerror=()=>rej(req.error)})}catch(err){try{localStorage.setItem('petri-heil-pro',JSON.stringify(S))}catch(e){toast('Speicher voll! Sofort Backup exportieren.')}}}
function save(){lastSave=lastSave.catch(()=>{}).then(()=>dbSave());return lastSave}
function toast(text){let el=$('#toast');el.textContent=text;el.classList.add('show');clearTimeout(toastTimeout);toastTimeout=setTimeout(()=>el.classList.remove('show'),3800)}
function renderNav(){$('#nav-desktop').innerHTML=NAV.map(([p,t,i])=>`<button class="${page===p?'active':''}" data-page="${p}"><span class="ico">${i}</span>${h(t)}</button>`).join('');$('#nav-bottom').innerHTML=[NAV[0],NAV[1],NAV[2],NAV[5],NAV[9]].map(([p,t,i])=>`<button class="${page===p?'active':''}" data-page="${p}"><span class="ico">${i}</span>${t==='Backup & Einstellungen'?'Mehr':h(t.split(' ')[0])}</button>`).join('')}
function render(){const entry=NAV.find(x=>x[0]===page)||NAV[0];$('#crumb').textContent='PETRI HEIL PRO  /  '+entry[1].toUpperCase();$('#page-title').textContent=entry[1];renderNav();$('#main').innerHTML=({home:homeView,trophies:trophiesView,fish:fishView,exam:examView,rules:rulesView,clock:clockView,stats:statsView,gear:gearView,spots:spotsView,backup:backupView}[page]||homeView)();refreshConnection();updateClock()}
function goto(p){page=p;quiz=null;$('#sidebar').classList.remove('open');$('#mobile-shade').classList.remove('open');render();window.scrollTo({top:0,behavior:'instant'})}
function empty(icon,title,description,button=''){return `<div class="empty"><div class="empty-icon">${icon}</div><h3>${h(title)}</h3><p>${h(description)}</p>${button}</div>`}
function metric(label,val,sub,ico,highlight=0){return `<div class="card metric ${highlight?'highlight':''}"><div class="label">${label}</div><div class="corner">${ico}</div><div class="value">${val}</div><div class="sub">${sub}</div></div>`}
function legalQuick(fish){let rule=DATA.rules.rules[S.state]?.[fish];return rule?`<span class="pill pill-lime">${h(rule[0]+' cm')} · ${h(rule[1])}</span>`:`<span class="pill">Vorschrift nicht hinterlegt</span>`}
function photoValid(src){return typeof src==='string'&&/^data:image\/(jpeg|jpg|png|webp);base64,/i.test(src)}
function trophyPicture(t){let p=arr(t.photos).find(photoValid);return p?`<img src="${p}" alt="Fangfoto ${h(t.fish)}" loading="lazy">`:'<span style="font-size:66px;color:#baf073">♓</span>'}
function topTrophies(){return [...S.trophies].filter(t=>Number(t.cm)>0).sort((a,b)=>Number(b.cm)-Number(a.cm)||Number(b.grams||0)-Number(a.grams||0)).slice(0,3)}
function rankCards(){const top=topTrophies();return `<div class="rank-grid">${[0,1,2].map(i=>{const t=top[i],lab=['GOLD','SILBER','BRONZE'][i];return `<div class="rank ${['gold','silver','bronze'][i]}"><div class="medal">${['🥇','🥈','🥉'][i]}</div><div class="place">${lab} · PLATZ ${i+1}</div>${t?`<strong>${h(t.fish)}</strong><div class="measure">${fmt(t.cm)} cm</div><div class="foot">${h(weightText(t.grams))} · ${dateDe(t.date)}</div>`:`<strong>Noch frei</strong><div class="foot">Erfasse einen Fang mit Länge</div>`}</div>`}).join('')}</div>`}
function catchesByWeight(){return S.trophies.filter(t=>Number(t.grams)>0)}
function getTotals(){return {weight:catchesByWeight().reduce((a,b)=>a+Number(b.grams),0),seconds:S.sessions.reduce((a,b)=>a+(Number(b.seconds)||0),0)}}
function homeView(){const tot=getTotals(),max=topTrophies()[0],last=[...S.trophies].sort((a,b)=>new Date(b.date)-new Date(a.date)).slice(0,3);return `<section class="hero"><div><div class="hero-label">DEIN ANGELABENTEUER BEGINNT HIER</div><h2>Jeder Fang.<br><strong>Eine Geschichte.</strong></h2><p>Dein persönliches Fangbuch, Fischlexikon und Angelschein-Trainer – alles an einem Ort, auch ohne Internet.</p><div class="flex wrap"><button class="button button-primary" data-action="openCatch">＋ Fang eintragen</button><button class="button button-outline" data-page="exam">Jetzt lernen →</button></div></div><img src="assets/petri-logo.webp" alt="Petri Heil Logo mit Hecht"></section><div class="grid cards4">${metric('DEINE FÄNGE',S.trophies.length,'Fische erfasst','♓',1)}${metric('GESAMTGEWICHT',fmt(tot.weight/1000,3),'kg · nur gewogene Fische','⚖')}${metric('BESTER FANG',max?fmt(max.cm):'–',max?'cm · '+h(max.fish):'Noch kein Rekord','♛')}${metric('ANGELZEIT',fmt(tot.seconds/3600,1),'Stunden · abgeschlossene Sessions','◷')}</div><section class="section"><div class="section-head"><h2>Dein Fang-Podium</h2><button class="text-button" data-page="trophies">Alle Trophäen →</button></div>${rankCards()}</section><div class="grid cards2 section"><div class="card"><div class="section-head"><h2>Letzte Fänge</h2><button class="text-button" data-page="trophies">Ansehen →</button></div>${last.length?last.map(t=>`<button class="session-row" style="background:none;color:inherit;border-left:0;border-top:0;border-right:0;width:100%;text-align:left" data-trophy="${h(t.id)}"><div><strong>${h(t.fish)}</strong><br><span>${dateDe(t.date)} · ${h(t.location||'Ohne Ort')}</span></div><strong class="accent">${fmt(t.cm)} cm</strong></button>`).join(''):empty('♓','Noch keine Fänge','Starte dein persönliches Fangbuch.','<button class="button button-primary" data-action="openCatch">Ersten Fang eintragen</button>')}</div><div class="card"><div class="section-head"><h2>Direkt loslegen</h2></div><div class="grid" style="gap:9px">${[['fish','♓','Fischarten entdecken','162 Einträge: Süß- und Salzwasser'],['clock','◷','Angelzeit starten','Sitzungen und Zeiten erfassen'],['rules','⚖','Schonzeiten prüfen','Bundesland wählen und Quelle öffnen'],['spots','⌖','Angelspots verwalten','Orte mit GPS speichern']].map(([p,ic,t,sub])=>`<button class="session-row" style="background:none;color:inherit;border-left:0;border-top:0;border-right:0;width:100%;text-align:left" data-page="${p}"><span style="font-size:25px">${ic}</span><span class="grow"><strong>${t}</strong><br><span>${sub}</span></span><b>→</b></button>`).join('')}</div></div></div><div class="warning section">Rechtliches: Schonzeiten, Mindestmaße und Entnahmeregeln gelten je nach Bundesland, Küste und Gewässer. Nur NRW und Bayern besitzen hier eine geprüfte Teilauswahl (Stand der Quellen: Oktober 2026). Offline gespeicherte Werte können veralten.</div>`}
function trophiesView(){const sort=S.trophies.slice().sort((a,b)=>new Date(b.date)-new Date(a.date));const view=trophyFilter==='Alle'?sort:sort.filter(x=>x.fish===trophyFilter);const fishSelect=[...new Set(S.trophies.map(t=>t.fish))].sort((a,b)=>a.localeCompare(b,'de'));return `<div class="section-head"><div><h2>Deine persönlichen Rekorde</h2><p>Ranking nach Länge; bei gleicher Länge nach Gewicht.</p></div><button class="button button-primary" data-action="openCatch">＋ Neuer Fang</button></div>${rankCards()}<section class="section"><div class="toolbar"><div class="grow"><h2>Fangbuch <span class="pill">${S.trophies.length} Einträge</span></h2></div><select class="control select-compact" id="trophy-filter"><option>Alle</option>${fishSelect.map(f=>`<option ${trophyFilter===f?'selected':''}>${h(f)}</option>`).join('')}</select></div>${view.length?`<div class="trophy-grid">${view.map(t=>`<button class="trophy" data-trophy="${h(t.id)}"><div class="trophy-cover">${trophyPicture(t)}</div><div class="trophy-body"><h3>${h(t.fish)}</h3><div class="numbers"><span>${fmt(t.cm)} cm</span><span>${h(weightText(t.grams))}</span></div><div class="meta">${dateDe(t.date)} · ${h(t.location||'Ort nicht angegeben')}</div></div></button>`).join('')}</div>`:empty('♛','Keine Fänge vorhanden','Fänge werden mit Bildern und Messwerten direkt hier angezeigt.','<button class="button button-primary" data-action="openCatch">Fang hinzufügen</button>')}</section>`}
function fishView(){let groups=['Alle',...new Set(DATA.fish.map(f=>f.group))];return `<div class="section-head"><div><h2>Fischlexikon</h2><p>${DATA.fish.length} Arten und Formen – Fischkunde, Köder, Gefahren und Verzehrhinweise.</p></div><span class="pill pill-lime">OFFLINE</span></div><div class="warning floating-note">Ein umfangreicher Lernkatalog, keine vollständige amtliche Artenliste. Ein Fisch gilt nicht automatisch als entnehmbar oder essbar. Artenschutz, Schonzeiten, örtliche Verbote und ggf. Schadstoffbelastung prüfen.</div><div class="toolbar"><div class="searchbar"><span>⌕</span><input id="fish-search" class="control" value="${h(fishFilter.search)}" placeholder="Fischname oder wissenschaftlicher Name" autocomplete="off"></div><select class="control select-compact" id="fish-water"><option ${fishFilter.water==='Alle'?'selected':''}>Alle</option><option ${fishFilter.water==='Süßwasser'?'selected':''}>Süßwasser</option><option ${fishFilter.water==='Salzwasser'?'selected':''}>Salzwasser</option></select><select class="control select-compact" id="fish-group">${groups.map(x=>`<option ${fishFilter.group===x?'selected':''}>${h(x)}</option>`).join('')}</select></div><div class="mini-label" id="fish-count"></div><div id="fish-list" style="margin-top:12px"></div>`}
function updateFishList(){const target=$('#fish-list');if(!target)return;let search=fishFilter.search.toLocaleLowerCase('de-DE').trim();let filtered=DATA.fish.filter(f=>(fishFilter.water==='Alle'||f.water===fishFilter.water)&&(fishFilter.group==='Alle'||f.group===fishFilter.group)&&(!search||(f.name+' '+f.latin+' '+f.group).toLocaleLowerCase('de-DE').includes(search)));$('#fish-count').textContent=`${filtered.length} Treffer`;target.innerHTML=filtered.length?`<div class="fish-grid">${filtered.map(f=>`<button class="fish-card" data-fish="${h(f.id)}"><div class="fish-card-top"><div class="fish-icon">${f.water==='Salzwasser'?'≋':'♓'}</div><div><h3>${h(f.name)}</h3><em>${h(f.latin)}</em></div></div><div class="fish-card-footer"><span>${h(f.group)}</span><strong>Mehr ansehen →</strong></div></button>`).join('')}</div>`:empty('⌕','Keine Treffer','Versuche einen anderen Suchbegriff oder Filter.')}
function openFish(fishId){let f=DATA.fish.find(x=>x.id===fishId);if(!f)return;let link=DATA.rules.sources[S.state];openModal(`<div class="modal-head"><div><div class="eyebrow">FISCHKUNDE · ${h(f.water.toUpperCase())}</div><h2>${h(f.name)}</h2><span class="muted small"><i>${h(f.latin)}</i> · ${h(f.group)}</span></div><button class="icon-button" data-action="closeModal">✕</button></div><div class="modal-body"><div class="fish-icon" style="width:80px;height:76px;font-size:42px;margin-bottom:16px">♓</div><p>${h(f.desc)}</p><div class="flex wrap" style="margin-bottom:15px"><span class="pill ${f.venom?'pill-red':''}">${f.venom?'Achtung: giftige Stacheln':'Keine Giftigkeit im Katalog belegt'}</span><span class="pill">${h(f.edible==='typischer Speisefisch'?'Speisefisch (rechtliche Freigabe prüfen)':'Verzehr nur nach Artprüfung')}</span></div><div class="grid cards2"><div class="card"><div class="mini-label">VORKOMMEN</div><p class="small">${h(f.habitat)}</p></div><div class="card"><div class="mini-label">KÖDER / MONTAGEN</div><p class="small">${h(f.baits)}</p></div><div class="card"><div class="mini-label">STACHELN / GEFAHREN</div><p class="small">${h(f.hazard)}</p></div><div class="card"><div class="mini-label">VERZEHR</div><p class="small">${h(f.food)}</p></div></div><div class="divider"></div><h3>Schonmaße & Zeiten · ${h(S.state)}</h3><div style="margin:12px 0">${legalQuick(f.name)}</div><div class="warning">Angaben sind nur ein Teilauszug aus dem Landesrecht, keine Freigabe. Fischereierlaubnis, Schutzgebiet, EU-/Küstenregeln und Gewässerordnung können vorgehen.</div>${link?`<p class="small"><a href="${h(link)}" target="_blank" rel="noopener noreferrer">Amtlichen Rechtstext öffnen ↗ (Internet nötig)</a></p>`:''}</div><div class="modal-actions"><button class="button button-ghost" data-action="closeModal">Schließen</button><button class="button button-primary" data-action="openCatch" data-prefish="${h(f.name)}">Fang dieser Art erfassen</button></div>`)}
function rulesView(){const rules=DATA.rules.rules[S.state]||null,url=DATA.rules.sources[S.state];return `<div class="section-head"><div><h2>Schonzeiten & Mindestmaße</h2><p>Bundesland wählen – nur geprüfte Teilauszüge werden mit Zahlen angezeigt.</p></div></div><div class="toolbar"><select class="control" style="max-width:320px" id="state-select">${DATA.rules.states.map(st=>`<option ${S.state===st?'selected':''}>${h(st)}</option>`).join('')}</select>${url?`<a class="button button-outline" href="${h(url)}" target="_blank" rel="noopener noreferrer">Amtliche Quelle ↗</a>`:''}</div><div class="warning floating-note"><strong>Wichtig:</strong> Alle Werte sind ohne Gewähr auf Aktualität am Fangtag. Gewässerspezifische strengere Regeln, Schongebiete, Fanglimits und EU-/Küstenfischerei können hinzukommen. ${h(DATA.rules.note)}</div>${rules?`<div class="card"><div class="flex wrap between"><h2>Geprüfte Teilauswahl · ${h(S.state)}</h2><span class="pill pill-lime">Quelle geprüft: 09.10.2026</span></div><div class="table-scroll"><table class="table"><thead><tr><th>Art</th><th>Mindestmaß</th><th>Schonzeit / Einschränkung</th></tr></thead><tbody>${Object.entries(rules).sort((a,b)=>a[0].localeCompare(b[0],'de')).map(([f,[cm,season]])=>`<tr><td><strong>${h(f)}</strong></td><td class="nowrap">${fmt(cm,0)} cm</td><td>${h(season)}</td></tr>`).join('')}</tbody></table></div><p class="small muted">${S.state==='Bayern'?'Die allgemeine bayerische Anlage unterscheidet teilweise Flussgebietseinheiten. Das Bodensee-Sonderrecht und andere abweichende Regeln sind hier nicht abgebildet.':'Die Angaben für NRW ergeben sich aus §§ 2–3 der LFischVO; zusätzliche europäische/regionale Bestimmungen sind möglich.'}</p></div>`:`<div class="card">${empty('⚖','Keine geprüften Landeswerte hinterlegt','Für dieses Bundesland wurden bewusst keine Zahlen erfunden. Prüfe die aktuelle Landesfischereiverordnung, die zuständige Fischereibehörde und die Gewässerordnung vor jedem Angeltrip.')}<p class="muted small">Du kannst trotzdem im Fischlexikon und im Angelschein-Trainer mit bundesweiten Grundlagen arbeiten.</p></div>`}<div class="card section"><h3>Prüfungs- und Rechtsquellen</h3><p class="muted small">NRW: Landesfischereiverordnung (Fassung 03.07.2026) und Fischerprüfungsordnung. Bayern: AVBayFiG Anlage (ab 01.06.2025). Schleswig-Holstein: Hinweise der Landesverwaltung vom 26.02.2026.</p><div class="flex wrap">${[['NRW Landesrecht','https://recht.nrw.de/lrgv/rechtsverordnung/03072026-landesfischereiverordnung-lfischvo/'],['NRW Prüfung','https://recht.nrw.de/lrgv/rechtsverordnung/03072026-verordnung-ueber-die-fischerpruefung/'],['Bayern Anlage','https://www.gesetze-bayern.de/Content/Document/BayAVFiG-ANL_1'],['SH Landesinfos','https://www.schleswig-holstein.de/DE/fachinhalte/F/fischerei/gesetzeVerordnungen']].map(([t,l])=>`<a class="button button-ghost button-small" href="${l}" target="_blank" rel="noopener noreferrer">${t} ↗</a>`).join('')}</div></div>`}
function questionPool(){return DATA.questions.filter(q=>!q.state||q.state===S.state)}
function shuffled(a){return [...a].sort(()=>Math.random()-.5)}
function makeQuiz(type){const pool=questionPool();let pick=[];if(type==='exam'&&S.state==='Nordrhein-Westfalen'){for(const cat of ['Allgemeine Fischkunde','Spezielle Fischkunde','Gewässerkunde und Fischhege','Natur- und Tierschutz','Gerätekunde','Gesetzeskunde'])pick.push(...shuffled(pool.filter(x=>x.category===cat)).slice(0,10))}else pick=shuffled(pool).slice(0,type==='exam'?30:20);return{type,questions:shuffled(pick).map(q=>({...q,shown:shuffled(q.options.map((txt,i)=>({txt,correct:i===q.answer})))})),answers:{},index:0,started:Date.now(),duration:type==='exam'?(S.state==='Nordrhein-Westfalen'?3600:1800):0,finished:false,state:S.state}}
function examView(){if(quiz?.finished)return examResultView();if(quiz)return questionView();return `<div class="section-head"><div><h2>Angelschein-Trainer</h2><p>${DATA.questions.length} selbst formulierte Lernfragen · nach Bundesland gefiltert.</p></div><span class="pill pill-lime">OFFLINE TRAINING</span></div><div class="warning floating-note">Diese App enthält <strong>eigene Übungsfragen, keinen vollständigen amtlichen Fragenkatalog</strong>. Der Prüfungsmodus ist eine Simulation und ersetzt weder amtliche Prüfungsunterlagen noch die praktische Prüfung. In anderen Ländern als NRW/Bayern sind keine spezifisch geprüften Landesrechtsfragen enthalten.</div><div class="grid cards2"><div class="card"><span class="pill pill-lime">LERNSYSTEM</span><h2 style="font-size:25px;margin:16px 0 9px">Üben & Verstehen</h2><p class="muted">20 zufällige Fragen mit direktem Feedback und Erklärungen zu den sechs Themengebieten.</p><div class="divider"></div><button class="button button-primary" data-action="startLearn">Training starten →</button></div><div class="card"><span class="pill pill-gold">PRÜFUNGSMODUS</span><h2 style="font-size:25px;margin:16px 0 9px">Wissen testen</h2><p class="muted">${S.state==='Nordrhein-Westfalen'?'60 Fragen, 60 Minuten. Je zehn Fragen aus sechs Bereichen, in Anlehnung an die NRW-Prüfungsordnung.':'30 Übungsfragen, 30 Minuten. Kein amtliches Prüfungsformat.'} Auswertung nach Abschluss.</p><div class="divider"></div><button class="button button-outline" data-action="startExam">Simulation starten →</button></div></div><div class="card section"><div class="section-head"><h2>Dein Bundesland</h2><span class="pill">${h(S.state)}</span></div><select class="control" style="max-width:340px" id="state-select">${DATA.rules.states.map(st=>`<option ${S.state===st?'selected':''}>${h(st)}</option>`).join('')}</select><p class="small muted" style="margin:12px 0 0">${S.state==='Nordrhein-Westfalen'?'NRW: Schriftliche Prüfung gemäß Prüfungsordnung mit 60 Fragen in 60 Minuten; zusätzlich praktischer Prüfungsteil.':S.state==='Bayern'?'Bayerische Landesfragen: amtlich geprüfte Rechtsauszüge; die echte Prüfung ist umfangreicher.':'Bundesweite Grundlagenfragen vorhanden; keine geprüften landesspezifischen Prüfungstexte.'}</p></div><div class="card section"><h2>Deine letzten Ergebnisse</h2>${S.examHistory.length?S.examHistory.slice(-5).reverse().map(e=>`<div class="session-row"><div><strong>${e.type==='exam'?'Prüfungssimulation':'Training'}</strong><br><span>${dateDe(e.date)} · ${h(e.state)}</span></div><strong class="accent">${fmt(100*e.correct/e.total,0)} %</strong></div>`).join(''):empty('▤','Noch kein Test','Deine Prüfungsergebnisse werden lokal gespeichert.')}</div>`}
function questionView(){const q=quiz.questions[quiz.index],idx=quiz.index,selected=quiz.answers[q.id],isLearn=quiz.type==='learn';return `<div class="quiz-panel"><div class="flex between wrap" style="margin-bottom:14px"><span class="pill ${quiz.type==='exam'?'pill-gold':'pill-lime'}">${quiz.type==='exam'?'PRÜFUNGSSIMULATION':'LERNSYSTEM'} · ${h(quiz.state)}</span><span class="mini-label" id="quiz-timer">${quiz.duration?timeText(Math.max(0,quiz.duration-Math.floor((Date.now()-quiz.started)/1000))):'Ohne Zeitlimit'}</span></div><div class="progress-track"><div style="width:${Math.round((idx+1)/quiz.questions.length*100)}%"></div></div><div class="flex between wrap" style="margin:17px 0"><span class="mini-label">FRAGE ${idx+1} VON ${quiz.questions.length}</span><span class="pill">${h(q.category)}</span></div><div class="card"><div class="quiz-question">${h(q.q)}</div>${q.shown.map((o,i)=>{let klass=selected===i?'selected':'';if(isLearn&&selected!==undefined)klass=o.correct?'correct':selected===i?'wrong':'';return `<button data-quiz-answer="${i}" class="quiz-option ${klass}" ${isLearn&&selected!==undefined?'disabled':''}><span class="option-letter">${'ABCD'[i]}</span>${h(o.txt)}</button>`}).join('')}${isLearn&&selected!==undefined?`<div class="explain"><strong>${q.shown[selected]?.correct?'Richtig!':'Nicht ganz.'}</strong><p style="margin:7px 0 0">${h(q.explanation)}</p></div>`:''}<div class="divider"></div><div class="flex between wrap"><button class="button button-ghost" data-action="abortQuiz">Abbrechen</button><div class="flex wrap">${quiz.type==='exam'&&idx>0?`<button class="button button-ghost" data-action="prevQuestion">← Zurück</button>`:''}<button class="button button-primary" data-action="nextQuestion" ${selected===undefined?'disabled':''}>${idx===quiz.questions.length-1?'Auswerten':'Weiter →'}</button></div></div></div></div>`}
function finishQuiz(){if(!quiz||quiz.finished)return;quiz.finished=true;let correct=quiz.questions.filter(q=>q.shown[quiz.answers[q.id]]?.correct).length;S.examHistory.push({id:id(),date:new Date().toISOString(),type:quiz.type,state:quiz.state,total:quiz.questions.length,correct});save();render()}
function examResultView(){let correct=quiz.questions.filter(q=>q.shown[quiz.answers[q.id]]?.correct).length,total=quiz.questions.length,pct=Math.round(correct/total*100),mistakes=quiz.questions.filter(q=>!q.shown[quiz.answers[q.id]]?.correct);return `<div class="quiz-panel"><div class="card" style="text-align:center"><div style="font-size:45px">${pct>=75?'✦':'▤'}</div><p class="eyebrow">AUSWERTUNG</p><h2 style="font-size:32px">${pct}% richtig</h2><div class="big-stat accent">${correct} / ${total}</div><p class="muted">${pct>=75?'Gute Leistung in dieser Übung.':'Du kannst Wissenslücken gezielt wiederholen.'} Dies ist keine amtliche Bestehensbewertung.</p><div class="flex wrap" style="justify-content:center"><button class="button button-primary" data-action="finishGoHome">Neuen Test wählen</button><button class="button button-ghost" data-action="startLearn">Noch einmal üben</button></div></div><div class="card section"><h2>Fragen mit Nachholbedarf (${mistakes.length})</h2>${mistakes.length?mistakes.map(q=>`<div class="session-row" style="display:block"><strong>${h(q.q)}</strong><p class="small" style="margin:6px 0"><span>Richtige Antwort: ${h(q.shown.find(o=>o.correct)?.txt)}</span></p><p class="small muted" style="margin:0">${h(q.explanation)}</p></div>`).join(''):empty('✦','Alle Fragen richtig','Dein Übungsdurchgang war fehlerfrei.')}</div></div>`}
function timerElapsed(){if(!S.timer.running)return 0;let end=S.timer.paused?new Date(S.timer.pausedAt).getTime():Date.now();return Math.max(0,Math.floor((end-new Date(S.timer.startedAt).getTime()-(S.timer.pausedMs||0))/1000))}
function clockView(){let running=S.timer.running,paused=S.timer.paused;return `<div class="section-head"><div><h2>Deine Angelzeit im Überblick</h2><p>Uhr starten, pausieren und Sessions mit Datum speichern.</p></div><span class="pill ${running?'pill-lime':''}">${running?(paused?'PAUSIERT':'LÄUFT'):'BEREIT'}</span></div><div class="grid cards2"><div class="card"><div class="clock-circle"><span class="clock-symbol">◷</span><span class="clock-caption">AKTUELLE ANGELZEIT</span><div class="time-clock" id="timer-clock">${timeText(timerElapsed())}</div><span class="mini-label">${running?datetimeDe(S.timer.startedAt):'Noch keine aktive Session'}</span></div><div class="flex wrap" style="justify-content:center">${!running?`<button class="button button-primary" data-action="timerStart">▶ Angelzeit starten</button>`:`<button class="button button-outline" data-action="timerToggle">${paused?'▶ Fortsetzen':'Ⅱ Pause'}</button><button class="button button-primary" data-action="timerStop">■ Beenden & speichern</button>`}</div><div class="divider"></div><div class="notice">Die Uhr läuft per Startzeitstempel weiter, wenn du die App schließt. Pausen werden abgezogen. Erst abgeschlossene Sessions werden gezählt.</div></div><div class="card"><h2>Zeitstatistik</h2>${sessionStats().map(([t,secs])=>`<div class="session-row"><strong>${t}</strong><strong class="accent">${durationText(secs)}</strong></div>`).join('')}<div class="divider"></div><h3>Letzte Angelzeiten</h3>${S.sessions.length?S.sessions.slice().sort((a,b)=>new Date(b.start)-new Date(a.start)).slice(0,7).map(s=>`<div class="session-row"><div><strong>${dateDe(s.start)}</strong><br><span>${datetimeDe(s.start)} – ${new Date(s.end).toLocaleTimeString('de-DE',{hour:'2-digit',minute:'2-digit'})}</span></div><div class="text-right"><strong class="accent">${durationText(s.seconds)}</strong><br><button class="text-button small" data-delete-session="${h(s.id)}">Löschen</button></div></div>`).join(''):empty('◷','Noch keine Angelzeit','Starte die Uhr vor deinem nächsten Angelausflug.')}</div></div>`}
function mondayOf(d){let x=new Date(d),day=(x.getDay()+6)%7;x.setHours(0,0,0,0);x.setDate(x.getDate()-day);return x}
function periodMatch(date,period){let v=new Date(date),now=new Date();if(isNaN(v))return false;if(period==='Tag')return v.toDateString()===now.toDateString();if(period==='Woche')return v>=mondayOf(now)&&v<mondayOf(new Date(mondayOf(now).getTime()+7*86400000));if(period==='Monat')return v.getFullYear()===now.getFullYear()&&v.getMonth()===now.getMonth();if(period==='Jahr')return v.getFullYear()===now.getFullYear();return true}
function sessionStats(){return ['Tag','Woche','Monat','Jahr'].map(p=>[p,S.sessions.filter(s=>periodMatch(s.start,p)).reduce((a,s)=>a+Number(s.seconds||0),0)])}
function weightStats(){let c=catchesByWeight();return ['Tag','Woche','Monat','Jahr'].map(p=>[p,c.filter(t=>periodMatch(t.date,p)).reduce((a,t)=>a+Number(t.grams),0)])}
function bars(data,unit='g'){let max=Math.max(1,...data.map(x=>x[1]));return data.map(([name,num])=>`<div class="bar-row"><strong>${h(name)}</strong><div class="bar-bg"><div class="bar-fill" style="width:${num?Math.max(3,Math.round(num/max*100)):0}%"></div></div><div class="text-right"><strong>${unit==='g'?weightText(num):durationText(num)}</strong></div></div>`).join('')}
function statsView(){let tot=getTotals(),fishes=catchesByWeight(),byFish=new Map();for(const t of fishes)byFish.set(t.fish,(byFish.get(t.fish)||0)+Number(t.grams));let summary=[...byFish].sort((a,b)=>b[1]-a[1]).slice(0,7);let months=Array.from({length:6},(_,i)=>{let d=new Date();d.setDate(1);d.setMonth(d.getMonth()-(5-i));return [d.toLocaleString('de-DE',{month:'short'}),fishes.filter(t=>{let x=new Date(t.date);return x.getFullYear()===d.getFullYear()&&x.getMonth()===d.getMonth()}).reduce((a,t)=>a+Number(t.grams),0)]});return `<div class="section-head"><div><h2>Deine Fangstatistik</h2><p>Gewicht nur aus Fängen mit einem positiven Gramm- oder Kilogrammwert.</p></div></div><div class="grid cards4">${metric('GEWICHT TOTAL',fmt(tot.weight/1000,3),'kg · '+fishes.length+' gewogene Fische','⚖',1)}${metric('GEWOGENE FÄNGE',fishes.length,'von '+S.trophies.length+' Fängen','♓')}${metric('ANGELZEIT TOTAL',fmt(tot.seconds/3600,1),'Stunden aus Sessions','◷')}${metric('Ø FANGGEWICHT',fishes.length?fmt((tot.weight/fishes.length)/1000,3):'0','kg je gewogenem Fang','▥')}</div><div class="grid cards2 section"><div class="card"><h2>Gewicht nach Zeitraum</h2><p class="small muted">Tag, Woche, Monat und Jahr</p>${bars(weightStats())}</div><div class="card"><h2>Angelzeit nach Zeitraum</h2><p class="small muted">Abgeschlossene Sessions</p>${bars(sessionStats(),'sec')}</div></div><div class="grid cards2 section"><div class="card"><h2>Fanggewicht – 6 Monate</h2><div class="bars-small">${months.map(([nm,n])=>`<div class="bar-column" title="${h(nm)}: ${h(weightText(n))}"><div class="bar" style="height:${Math.round(n/Math.max(1,...months.map(x=>x[1]))*105)}px"></div><label>${h(nm)}</label></div>`).join('')}</div></div><div class="card"><h2>Gewicht nach Fischart</h2>${summary.length?bars(summary):empty('▥','Noch keine Gewichtsdaten','Trage mindestens einen Fang mit Gramm oder Kilogramm ein.')}</div></div><div class="notice section">Nicht gewogene Fische zählen weiterhin im Fangbuch und im Längen-Ranking, aber nicht in die Gewichtsberechnung.</div>`}
const GEAR=[
['Ruten','🎣','Spinnrute','Für aktiv geführte Kunstköder; Wurfgewicht zur Ködergröße passend auswählen.','Hecht / Zander / Barsch'],
['Ruten','🎣','Feederrute','Grundangeln mit Futterkorb und sensibler Bissanzeiger-Spitze.','Brasse / Barbe / Rotauge'],
['Ruten','🎣','Karpfenrute','Kräftige Rute für Karpfenmontagen und einen kontrollierten Drill.','Karpfen / Schleie'],
['Ruten','🎣','Fliegenrute','Leichte Kunstfliegen werden mittels spezieller Fliegenschnur geworfen.','Forelle / Äsche'],
['Ruten','🎣','Brandungsrute','Lange Rute zum Angeln vom Strand mit Grundmontagen.','Plattfische / Küstenfische'],
['Köder','🪝','Gummifisch & Jig','Weichplastik-Kunstköder an einem beschwerten Jigkopf.','Zander / Barsch / Hecht'],
['Köder','🪝','Wobbler','Schwimmender, sinkender oder schwebender Kunstköder zum aktiven Führen.','Hecht / Zander / Barsch / Forelle'],
['Köder','🪝','Spinner & Blinker','Drehendes bzw. taumelndes Metall erzeugt Bewegungs- und Lichtreize.','Forelle / Hecht / Barsch'],
['Köder','🪝','Boilie','Fester Karpfenköder, oft am Haarvorfach befestigt.','Karpfen'],
['Köder','🪝','Mais & Teig','Häufige Köder beim Ansitz auf Friedfische.','Karpfen / Schleie / Brasse'],
['Köder','🪝','Würmer & Maden','Naturköder beim Grund- und Posenangeln, soweit vor Ort zulässig.','Friedfische / Barsch / Forelle'],
['Köder','🪝','Pilker & Paternoster','Meeresmontagen mit Kunstködern, je nach Fangziel und Gesetz.','Hering / Makrele / Meer'],
['Schnur & Vorfach','〰','Monofile Schnur','Etwas dehnfähig; Knoten und Abrieb prüfen.','Posen-, Grund- und Allroundangeln'],
['Schnur & Vorfach','〰','Geflochtene Schnur','Sehr geringe Dehnung und direkter Kontakt zum Köder.','Spinnfischen'],
['Schnur & Vorfach','〰','Fluorocarbon','Vorfachmaterial, meist abriebbeständig; nicht automatisch hechtsicher.','Barsch / Zander'],
['Schnur & Vorfach','〰','Bissfestes Vorfach','Beim Hecht ein zuverlässig bissfestes Vorfach verwenden.','Hecht'],
['Kescher & Zubehör','⚓','Gummierter Kescher','Ausreichend großer Kescher zum möglichst schonenden Landen.','Alle Zielfische'],
['Kescher & Zubehör','⚓','Abhakmatte','Feuchte Unterlage zur Vermeidung von Verletzungen bei der Versorgung.','Größere Fische'],
['Kescher & Zubehör','⚓','Maßband & Waage','Fischlänge und Gewicht dokumentieren.','Fangbuch und Mindestmaß'],
['Kescher & Zubehör','⚓','Hakenlöser & Zange','Hilfsmittel zum sicheren, zügigen Lösen von Haken.','Alle Fischarten'],
['Kescher & Zubehör','⚓','Rettungsweste','Sicherheitsausrüstung bei Bootsfahrten und gefährlichen Uferbereichen.','Boot / Küste']];
function gearView(){const groups=['Alle','Ruten','Köder','Schnur & Vorfach','Kescher & Zubehör'],view=gearTab==='Alle'?GEAR:GEAR.filter(x=>x[0]===gearTab);return `<div class="section-head"><div><h2>Ausrüstung, Ruten & Köder</h2><p>Funktion, Zielfische und allgemeine Anwendung.</p></div></div><div class="warning floating-note">Empfehlungen zur Technik sind keine rechtliche Erlaubnis. Während Schonzeiten können spezielle Methoden/Köder verboten sein. Lebende Köderfische sind in NRW untersagt.</div><div class="filter-pills" style="margin-bottom:19px">${groups.map(x=>`<button class="${gearTab===x?'active':''}" data-gear="${h(x)}">${h(x)}</button>`).join('')}</div><div class="grid cards3">${view.map(([group,icon,title,desc,sug])=>`<div class="card gear-card"><div class="gear-icon">${icon}</div><span class="pill">${h(group)}</span><h2 style="margin:12px 0">${h(title)}</h2><p>${h(desc)}</p><div class="divider"></div><div class="suggest">Typisch für: ${h(sug)}</div></div>`).join('')}</div>`}
function spotsView(){return `<div class="section-head"><div><h2>Angelspots & Routen</h2><p>Eigene Angelstellen und GPS-Koordinaten offline sichern.</p></div><button class="button button-primary" data-action="newSpot">＋ Spot speichern</button></div><div class="notice floating-note">GPS kann mit entsprechender Berechtigung ohne Internet funktionieren. Externe Routenplanung über OpenStreetMap erfordert Internet. Keine Offline-Karten enthalten. Der GPX-Export enthält Wegpunkte, keine berechnete Straßenroute.</div><p><button class="button button-ghost" data-action="gpxExport">⇩ Alle Angelplätze als GPX exportieren</button></p>${S.spots.length?`<div class="grid cards2">${S.spots.slice().sort((a,b)=>new Date(b.created)-new Date(a.created)).map(s=>`<div class="card spot-card"><div class="grow"><span class="pill">⌖ ANGELSPOT</span><h2 style="margin:12px 0 5px">${h(s.name)}</h2><p class="muted small">${h(s.notes||'Keine Notizen')}</p>${s.lat!=null&&s.lon!=null?`<p class="small accent">${fmt(s.lat,5)}°, ${fmt(s.lon,5)}°</p><a href="https://www.google.com/maps/dir/?api=1&destination=${encodeURIComponent(s.lat+','+s.lon)}&travelmode=driving" target="_blank" rel="noopener noreferrer" class="button button-outline button-small">Route online ↗</a>`:''}</div><button class="icon-button" data-delete-spot="${h(s.id)}" aria-label="Spot löschen">✕</button></div>`).join('')}</div>`:empty('⌖','Noch keine Angelspots','Speichere Plätze mit Namen, Notizen und optional GPS.')}`}
function backupView(){let photoCount=S.trophies.reduce((a,t)=>a+arr(t.photos).length,0);return `<div class="section-head"><div><h2>Daten & Einstellungen</h2><p>Private Daten bleiben lokal, bis du sie exportierst.</p></div><span class="pill pill-lime">BACKUP BEREIT</span></div><div class="grid cards2"><div class="card"><div class="gear-icon">⇩</div><h2>Datensicherung erstellen</h2><p class="muted small">Exportiert Fänge, Fotos, Gewichte, Sessions, Plätze und Lernstände in eine JSON-Datei.</p><div class="grid cards2" style="margin:20px 0">${metric('FÄNGE',S.trophies.length,'lokal gespeichert','♓')}${metric('FOTOS',photoCount,'im Backup enthalten','▧')}</div><button class="button button-primary" data-action="backupExport">⇩ Backup herunterladen</button></div><div class="card"><div class="gear-icon">⇧</div><h2>Backup wiederherstellen</h2><p class="muted small">JSON-Datei auswählen und bestehende Daten ersetzen oder ergänzen.</p><div class="field"><label>Importmethode</label><select id="backup-mode" class="control"><option value="merge">Zusammenführen (ohne Duplikate)</option><option value="replace">Alle vorhandenen Daten ersetzen</option></select></div><label class="button button-ghost" style="margin-top:16px">⇧ Backup-Datei auswählen<input id="backup-file" class="file-input" type="file" accept=".json,application/json"></label></div></div><div class="grid cards2 section"><div class="card"><h2>Bundesland auswählen</h2><p class="small muted">Rechtsauszüge und Übungsfragen anpassen.</p><select class="control" id="state-select">${DATA.rules.states.map(st=>`<option ${S.state===st?'selected':''}>${h(st)}</option>`).join('')}</select></div><div class="card"><h2>Speicherstatus</h2><div class="session-row"><strong>Version</strong><span>${VERSION}</span></div><div class="session-row"><strong>Datenhaltung</strong><span>Dieses Gerät · IndexedDB</span></div><div class="session-row"><strong>Offline-Nutzung</strong><span id="pwa-status">Prüfung läuft …</span></div></div></div><div class="card section"><h2>Auf dem iPhone installieren</h2><p class="small muted">Entpackten Ordner auf HTTPS-Webhost hochladen. In Safari öffnen → Teilen → „Zum Home-Bildschirm“. Nach dem ersten vollständigen Laden sind die App, Fischlexikon und Fragen offline nutzbar. Das direkte Öffnen von index.html aus einem lokalen Ordner ermöglicht keine PWA-Installation und kann GPS oder Speicher einschränken.</p><div class="warning">Keine Cloud-Synchronisation. Browserdaten löschen oder Gerätewechsel kann Fänge entfernen. Regelmäßig JSON-Backups außerhalb des Browsers speichern.</div></div><div class="card section"><div class="flex between wrap"><div><h2>Lokale Daten löschen</h2><p class="small muted">Vorher unbedingt Backup erstellen.</p></div><button class="button button-danger" data-action="wipeData">Daten löschen</button></div></div>`}
function openModal(inner,wide=false){$('#modal-root').innerHTML=`<div class="modal-overlay" id="modal-overlay"><div class="modal ${wide?'wide':''}" role="dialog" aria-modal="true">${inner}</div></div>`;$('.modal .icon-button')?.focus()}
function closeModal(){selectedPhotos=[];editId=null;$('#modal-root').innerHTML=''}
function catchForm(fishPreselect='',edit=null){editId=edit?.id||null;selectedPhotos=arr(edit?.photos).filter(photoValid);let current=edit?.fish||fishPreselect||'Hecht';let opts=[...DATA.fish].sort((a,b)=>a.name.localeCompare(b.name,'de'));const k=edit?.grams?Number(edit.grams)>=1000?'kg':'g':'kg';let weight=edit?.grams?Number(edit.grams)/(k==='kg'?1000:1):'';openModal(`<div class="modal-head"><div><div class="eyebrow">MEINE TROPHÄEN</div><h2>${edit?'Fang bearbeiten':'Neuen Fang erfassen'}</h2></div><button class="icon-button" data-action="closeModal" aria-label="Schließen">✕</button></div><form id="catch-form"><div class="modal-body"><div class="formgrid">
<div class="field span2"><label for="catch-fish">Fischart *</label><select class="control" name="fish" id="catch-fish" required>${opts.map(f=>`<option ${current===f.name?'selected':''}>${h(f.name)}</option>`).join('')}</select></div>
<div class="field"><label for="catch-cm">Größe (cm) *</label><input class="control" name="cm" id="catch-cm" type="number" min="0.1" max="999" step="0.1" placeholder="z. B. 85,5" value="${h(edit?.cm||'')}" required></div>
<div class="field"><label>Gewicht (optional)</label><div class="flex" style="gap:8px"><input class="control" name="weight" type="number" min="0" max="999999" step="0.001" placeholder="z. B. 3,42" value="${h(weight)}"><select class="control" name="unit" style="width:88px"><option ${k==='kg'?'selected':''}>kg</option><option ${k==='g'?'selected':''}>g</option></select></div></div>
<div class="field"><label for="catch-date">Datum & Uhrzeit *</label><input class="control" name="date" id="catch-date" type="datetime-local" value="${h(edit?.date?isoLocal(new Date(edit.date)):isoLocal())}" required></div>
<div class="field"><label for="catch-location">Angelort</label><div class="flex" style="gap:8px"><input class="control" name="location" id="catch-location" placeholder="See, Fluss oder Ort" value="${h(edit?.location||'')}"><button class="button button-ghost button-small" type="button" data-action="locateCatch" title="GPS verwenden">⌖</button></div></div>
<input type="hidden" name="lat" value="${h(edit?.lat??'')}"><input type="hidden" name="lon" value="${h(edit?.lon??'')}">
<div class="field span2"><label for="catch-notes">Notizen</label><textarea class="control" name="notes" id="catch-notes" placeholder="Köder, Wetter, Besonderheiten …">${h(edit?.notes||'')}</textarea></div>
<div class="field span2"><label>Fangfotos (bis 6 Bilder)</label><div class="upload-box"><div style="font-size:25px;margin-bottom:9px">▧</div><div class="flex wrap" style="justify-content:center"><label class="button button-ghost button-small">📷 Kamera<input class="file-input" type="file" accept="image/*" capture="environment" id="take-photo"></label><label class="button button-ghost button-small">▧ Aus Mediathek<input class="file-input" type="file" accept="image/*" multiple id="pick-photo"></label></div><div id="photo-preview" class="thumbs"></div><p class="mini-label" style="margin:10px 0 0">Fotos werden auf dem Gerät verkleinert, damit sie speicherbar bleiben. Originale in der Mediathek bleiben unverändert.</p></div></div>
</div></div><div class="modal-actions"><button class="button button-ghost" type="button" data-action="closeModal">Abbrechen</button><button class="button button-primary" type="submit">${edit?'Änderungen speichern':'Fang speichern'}</button></div></form>`,true);renderPhotoPreview()}
function renderPhotoPreview(){let box=$('#photo-preview');if(!box)return;box.innerHTML=selectedPhotos.map((p,i)=>`<div class="thumb"><img src="${p}" alt="Ausgewähltes Bild ${i+1}"><button type="button" class="delimg" data-remove-photo="${i}" aria-label="Foto entfernen">✕</button></div>`).join('')}
function imageToDataURL(file){return new Promise((resolve,reject)=>{if(!file.type.startsWith('image/'))return reject(new Error('Keine Bilddatei'));const url=URL.createObjectURL(file);let image=new Image();image.onload=()=>{try{let max=1600,scale=Math.min(1,max/Math.max(image.width,image.height));let can=document.createElement('canvas');can.width=Math.round(image.width*scale);can.height=Math.round(image.height*scale);let c=can.getContext('2d');c.drawImage(image,0,0,can.width,can.height);let data=can.toDataURL('image/jpeg',.79);URL.revokeObjectURL(url);resolve(data)}catch(e){URL.revokeObjectURL(url);reject(e)}};image.onerror=()=>{URL.revokeObjectURL(url);reject(new Error('Bild nicht lesbar'))};image.src=url})}
async function addPhotos(files){const list=arr([...files]).slice(0,6-selectedPhotos.length);if(!list.length)return toast('Maximal sechs Fotos pro Fang.');toast('Fotos werden verarbeitet …');for(let f of list){try{const data=await imageToDataURL(f);selectedPhotos.push(data)}catch(e){toast('Ein Bild konnte nicht gelesen werden.')}}renderPhotoPreview();toast(`${selectedPhotos.length} Fotos für den Fang ausgewählt.`)}
async function saveCatch(form){let fd=new FormData(form),fish=String(fd.get('fish')||'').trim(),cm=Number(fd.get('cm')),w=Number(fd.get('weight')),unit=fd.get('unit'),date=fd.get('date');if(!fish||!Number.isFinite(cm)||cm<=0||cm>999)return toast('Bitte eine gültige Fischlänge angeben.');if(w<0||!Number.isFinite(w))return toast('Ungültiges Gewicht.');let grams=fd.get('weight')===''?0:w*(unit==='kg'?1000:1);if(grams>9999999)return toast('Gewicht zu groß.');if(!date||isNaN(new Date(date).getTime()))return toast('Datum fehlt.');let old=S.trophies.find(t=>t.id===editId);let obj={id:old?.id||id(),fish,cm,grams:Math.round(grams*1000)/1000,date:new Date(date).toISOString(),location:String(fd.get('location')||'').trim().slice(0,200),lat:fd.get('lat')===''?null:Number(fd.get('lat')),lon:fd.get('lon')===''?null:Number(fd.get('lon')),notes:String(fd.get('notes')||'').trim().slice(0,2500),photos:[...selectedPhotos],created:old?.created||new Date().toISOString()};if(old)Object.assign(old,obj);else S.trophies.push(obj);closeModal();await save();toast(old?'Fang aktualisiert.':'Fang gespeichert.');render()}
function openTrophy(tid){let t=S.trophies.find(x=>x.id===tid);if(!t)return;const pics=arr(t.photos).filter(photoValid),main=pics[0];openModal(`<div class="modal-head"><div><div class="eyebrow">DEINE TROPHÄE</div><h2>${h(t.fish)}</h2></div><button class="icon-button" data-action="closeModal">✕</button></div><div class="modal-body">${main?`<img class="gallery-large" id="gallery-large" src="${main}" alt="Fangfoto">${pics.length>1?`<div class="gallery-small">${pics.map((p,i)=>`<img src="${p}" data-gallery="${i}" alt="Fangfoto ${i+1}">`).join('')}</div>`:''}`:'<div class="fish-icon" style="width:100%;height:175px;font-size:68px">♓</div>'}<div class="grid cards2 section"><div class="card"><div class="mini-label">LÄNGE</div><div class="big-stat accent">${fmt(t.cm)} <small>cm</small></div></div><div class="card"><div class="mini-label">GEWICHT</div><div class="big-stat">${h(weightText(t.grams))}</div></div></div><div class="session-row"><strong>Gefangen</strong><span>${datetimeDe(t.date)}</span></div><div class="session-row"><strong>Angelort</strong><span>${h(t.location||'–')}</span></div>${t.lat!=null&&t.lon!=null?`<div class="session-row"><strong>GPS</strong><span>${fmt(t.lat,5)}°, ${fmt(t.lon,5)}°</span></div>`:''}${t.notes?`<p class="small" style="margin-top:15px;white-space:pre-line">${h(t.notes)}</p>`:''}<div class="warning section">Die Erfassung eines Fangs ist keine Bestätigung, dass seine Entnahme erlaubt war. Prüfe gültige Schutz- und Gewässerbestimmungen.</div></div><div class="modal-actions"><button class="button button-danger" data-delete-trophy="${h(t.id)}">Löschen</button><button class="button button-ghost" data-action="closeModal">Schließen</button><button class="button button-primary" data-edit-trophy="${h(t.id)}">Bearbeiten</button></div>`,true)}
function spotForm(){openModal(`<div class="modal-head"><h2>Neuen Angelspot speichern</h2><button class="icon-button" data-action="closeModal">✕</button></div><form id="spot-form"><div class="modal-body"><div class="formgrid"><div class="field span2"><label>Bezeichnung *</label><input class="control" name="name" maxlength="120" placeholder="z. B. Uferstelle am See" required></div><div class="field span2"><label>Notizen</label><textarea class="control" name="notes" placeholder="Zufahrt, erlaubte Plätze, Besonderheiten"></textarea></div><div class="field"><label>Breitengrad</label><input class="control" type="number" min="-90" max="90" step="any" name="lat" placeholder="51.12345"></div><div class="field"><label>Längengrad</label><input class="control" type="number" min="-180" max="180" step="any" name="lon" placeholder="7.12345"></div></div><button type="button" class="button button-ghost button-small" style="margin-top:15px" data-action="locateSpot">⌖ Aktuellen Standort einsetzen</button></div><div class="modal-actions"><button type="button" class="button button-ghost" data-action="closeModal">Abbrechen</button><button type="submit" class="button button-primary">Spot speichern</button></div></form>`)}
function locate(target){if(!navigator.geolocation)return toast('Standortbestimmung nicht verfügbar.');toast('Standort wird ermittelt …');navigator.geolocation.getCurrentPosition(pos=>{let lat=pos.coords.latitude,lon=pos.coords.longitude,form=$(target);if(!form)return;form.elements.lat.value=lat.toFixed(7);form.elements.lon.value=lon.toFixed(7);if(target==='#catch-form'&&!form.elements.location.value)form.elements.location.value=`GPS ${lat.toFixed(5)}, ${lon.toFixed(5)}`;toast('GPS-Koordinaten übernommen.');},err=>toast('GPS nicht verfügbar: '+({1:'Zugriff verweigert',2:'Standort nicht ermittelbar',3:'Zeitüberschreitung'}[err.code]||'Bitte Berechtigung prüfen')), {enableHighAccuracy:true,timeout:14000,maximumAge:60000})}
function saveSpot(form){let f=new FormData(form),name=String(f.get('name')||'').trim();if(!name)return toast('Bitte Spot-Namen angeben.');let lat=f.get('lat')===''?null:Number(f.get('lat')),lon=f.get('lon')===''?null:Number(f.get('lon'));if(lat!=null&&(lat<-90||lat>90)||lon!=null&&(lon<-180||lon>180))return toast('GPS-Koordinaten außerhalb des zulässigen Bereichs.');S.spots.push({id:id(),name:name.slice(0,120),notes:String(f.get('notes')||'').slice(0,2500),lat,lon,created:new Date().toISOString()});save();closeModal();render();toast('Angelspot gespeichert.')}
function startTimer(){if(S.timer.running)return;S.timer={running:true,paused:false,startedAt:new Date().toISOString(),pausedAt:null,pausedMs:0};save();render()}
function toggleTimer(){if(!S.timer.running)return;if(S.timer.paused){S.timer.pausedMs+=Date.now()-new Date(S.timer.pausedAt).getTime();S.timer.paused=false;S.timer.pausedAt=null}else{S.timer.paused=true;S.timer.pausedAt=new Date().toISOString()}save();render()}
function stopTimer(){if(!S.timer.running)return;let seconds=timerElapsed();S.sessions.push({id:id(),start:S.timer.startedAt,end:new Date().toISOString(),seconds});S.timer=blank().timer;save();render();toast('Angelzeit gespeichert: '+durationText(seconds))}
function updateClock(){if(page==='clock'&&$('#timer-clock'))$('#timer-clock').textContent=timeText(timerElapsed());if(page==='exam'&&quiz&&!quiz.finished&&quiz.type==='exam'){let remaining=Math.max(0,quiz.duration-Math.floor((Date.now()-quiz.started)/1000));if($('#quiz-timer'))$('#quiz-timer').textContent=timeText(remaining);if(remaining===0)finishQuiz()}}
async function exportBackup(){await lastSave.catch(()=>{});const json=JSON.stringify({app:'petri-heil-pro',backupFormat:1,exportDate:new Date().toISOString(),data:S},null,2);let blob=new Blob([json],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='petri-heil-backup-'+new Date().toISOString().slice(0,10)+'.json';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);toast('Backup erstellt. Datei bitte sicher ablegen.')}
function safePhotoList(list){return arr(list).slice(0,6).filter(photoValid)}
function cleanBackup(data){if(!data||typeof data!=='object'||!Array.isArray(data.trophies)||!Array.isArray(data.sessions)||!Array.isArray(data.spots))throw new Error('Das Backup hat kein gültiges Datenformat.');return {trophies:data.trophies.slice(0,20000).filter(t=>t&&typeof t.id==='string'&&typeof t.fish==='string'&&Number(t.cm)>0).map(t=>({...t,fish:String(t.fish).slice(0,120),location:String(t.location||'').slice(0,200),notes:String(t.notes||'').slice(0,2500),photos:safePhotoList(t.photos),grams:Number(t.grams)||0})),sessions:data.sessions.filter(s=>s&&typeof s.id==='string'&&Number.isFinite(Number(s.seconds))).slice(0,30000),examHistory:arr(data.examHistory).slice(-1000),spots:data.spots.filter(s=>s&&typeof s.id==='string').slice(0,5000).map(s=>({...s,name:String(s.name||'').slice(0,120),notes:String(s.notes||'').slice(0,2500)}))}}
function unionById(a,b){let m=new Map(arr(a).map(x=>[x.id,x]));for(let v of b)if(!m.has(v.id))m.set(v.id,v);return [...m.values()]}
async function importBackup(file,method){if(!file)return;if(file.size>150*1024*1024)return toast('Datei zu groß (max. 150 MB).');try{let raw=JSON.parse(await file.text());if(raw.app!=='petri-heil-pro'||raw.backupFormat!==1)throw new Error('Keine kompatible Petri Heil Backup-Datei.');let incoming=cleanBackup(raw.data);if(method==='replace'){if(!confirm('ACHTUNG: Alle vorhandenen Daten werden durch das Backup ersetzt. Fortfahren?'))return;S={...blank(),...incoming,state:DATA.rules.states.includes(raw.data.state)?raw.data.state:S.state}}else{for(let key of ['trophies','sessions','spots','examHistory'])S[key]=unionById(S[key],incoming[key])}normalize();await save();render();toast('Backup erfolgreich '+(method==='replace'?'wiederhergestellt.':'zusammengeführt.'))}catch(err){toast('Backup konnte nicht importiert werden: '+err.message)}}
function xmlText(str){return String(str??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&apos;'}[c]))}
function exportGpx(){const coords=S.spots.filter(s=>s.lat!=null&&s.lon!=null&&Number.isFinite(Number(s.lat))&&Number.isFinite(Number(s.lon)));if(!coords.length)return toast('Keine Angelplätze mit GPS-Koordinaten zum Export.');const documentGpx='<?xml version="1.0" encoding="UTF-8"?>\n<gpx xmlns="http://www.topografix.com/GPX/1/1" version="1.1" creator="Petri Heil Pro">\n'+coords.map(s=>`<wpt lat="${Number(s.lat)}" lon="${Number(s.lon)}"><name>${xmlText(s.name)}</name><desc>${xmlText(s.notes)}</desc></wpt>`).join('\n')+'\n</gpx>';const url=URL.createObjectURL(new Blob([documentGpx],{type:'application/gpx+xml'}));const a=document.createElement('a');a.href=url;a.download='petri-heil-angelplaetze-'+new Date().toISOString().slice(0,10)+'.gpx';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000);toast(coords.length+' Wegpunkte als GPX exportiert.')}
function action(act,el){switch(act){case 'openCatch':catchForm(el.dataset.prefish||'');break;case 'closeModal':closeModal();break;case 'locateCatch':locate('#catch-form');break;case 'locateSpot':locate('#spot-form');break;case 'newSpot':spotForm();break;case 'timerStart':startTimer();break;case 'timerToggle':toggleTimer();break;case 'timerStop':stopTimer();break;case 'startLearn':quiz=makeQuiz('learn');render();break;case 'startExam':quiz=makeQuiz('exam');render();break;case 'abortQuiz':if(confirm('Übungsdurchgang wirklich abbrechen?')){quiz=null;render()}break;case 'prevQuestion':if(quiz?.index>0){quiz.index--;render()}break;case 'nextQuestion':if(!quiz)return;let q=quiz.questions[quiz.index];if(quiz.answers[q.id]===undefined)return;if(quiz.index<quiz.questions.length-1){quiz.index++;render()}else finishQuiz();break;case 'finishGoHome':quiz=null;render();break;case 'backupExport':exportBackup();break;case 'gpxExport':exportGpx();break;case 'wipeData':if(confirm('Alle Fänge, Fotos, Zeiten und Ergebnisse auf diesem Gerät unwiderruflich löschen? Vorher Backup erstellen!')){S=blank();save();render();toast('Lokale Daten zurückgesetzt.')}break}}
function bindEvents(){document.addEventListener('click',e=>{
let el=e.target.closest('[data-page]');if(el){goto(el.dataset.page);return}
el=e.target.closest('[data-action]');if(el){e.preventDefault();action(el.dataset.action,el);return}
el=e.target.closest('[data-fish]');if(el){openFish(el.dataset.fish);return}
el=e.target.closest('[data-trophy]');if(el){openTrophy(el.dataset.trophy);return}
el=e.target.closest('[data-edit-trophy]');if(el){let t=S.trophies.find(t=>t.id===el.dataset.editTrophy);if(t)catchForm('',t);return}
el=e.target.closest('[data-delete-trophy]');if(el){if(confirm('Diesen Fang inklusive aller Fotos löschen?')){S.trophies=S.trophies.filter(t=>t.id!==el.dataset.deleteTrophy);closeModal();save();render();toast('Fang gelöscht.')}return}
el=e.target.closest('[data-delete-session]');if(el){if(confirm('Angelzeit-Sitzung löschen?')){S.sessions=S.sessions.filter(s=>s.id!==el.dataset.deleteSession);save();render()}return}
el=e.target.closest('[data-delete-spot]');if(el){if(confirm('Diesen Angelspot löschen?')){S.spots=S.spots.filter(s=>s.id!==el.dataset.deleteSpot);save();render()}return}
el=e.target.closest('[data-remove-photo]');if(el){selectedPhotos.splice(Number(el.dataset.removePhoto),1);renderPhotoPreview();return}
el=e.target.closest('[data-gear]');if(el){gearTab=el.dataset.gear;render();return}
el=e.target.closest('[data-quiz-answer]');if(el&&quiz){let q=quiz.questions[quiz.index],index=Number(el.dataset.quizAnswer);if(quiz.type==='learn'&&quiz.answers[q.id]!==undefined)return;quiz.answers[q.id]=index;render();return}
el=e.target.closest('[data-gallery]');if(el){let main=$('#gallery-large');if(main)main.src=el.src;return}
if(e.target.id==='menu-toggle'){$('#sidebar').classList.toggle('open');$('#mobile-shade').classList.toggle('open');return}
if(e.target.id==='mobile-shade'){$('#sidebar').classList.remove('open');$('#mobile-shade').classList.remove('open');return}
if(e.target.id==='modal-overlay')closeModal();
});
document.addEventListener('submit',e=>{if(e.target.id==='catch-form'){e.preventDefault();saveCatch(e.target)}if(e.target.id==='spot-form'){e.preventDefault();saveSpot(e.target)}});
document.addEventListener('input',e=>{if(e.target.id==='fish-search'){fishFilter.search=e.target.value;clearTimeout(searchTimer);searchTimer=setTimeout(updateFishList,100)}});
document.addEventListener('change',async e=>{let t=e.target;if(t.id==='state-select'){S.state=t.value;await save();quiz=null;render();toast('Bundesland: '+S.state)}if(t.id==='fish-water'){fishFilter.water=t.value;updateFishList()}if(t.id==='fish-group'){fishFilter.group=t.value;updateFishList()}if(t.id==='trophy-filter'){trophyFilter=t.value;render()}if(t.id==='take-photo'||t.id==='pick-photo'){await addPhotos(t.files);t.value=''}if(t.id==='backup-file'){let method=$('#backup-mode')?.value||'merge';await importBackup(t.files[0],method);t.value=''}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&$('#modal-root').children.length)closeModal()});window.addEventListener('online',refreshConnection);window.addEventListener('offline',refreshConnection);
}
function refreshConnection(){const el=$('#network-tag');if(!el)return;el.textContent=navigator.onLine?'OFFLINE READY':'OFFLINE AKTIV';const status=$('#offline-state');if(status)status.textContent=navigator.onLine?'Bereit für offline':'Offline-Modus';const pw=$('#pwa-status');if(pw)pw.textContent=('serviceWorker' in navigator&&location.protocol==='https:')||location.hostname==='localhost'?'Service Worker verfügbar':'HTTPS-Hosting für Installation nötig'}
async function init(){bindEvents();await load();render();if(page==='fish')updateFishList();setInterval(updateClock,1000);if('serviceWorker'in navigator&&(location.protocol==='https:'||location.hostname==='localhost'))navigator.serviceWorker.register('./sw.js').then(()=>refreshConnection()).catch(()=>toast('Offline-Cache konnte nicht aktiviert werden.'));
if('storage'in navigator&&navigator.storage.persist)navigator.storage.persist().catch(()=>{})}
const originalRender=render;render=function(){originalRender();if(page==='fish')updateFishList()};
init();
